const _wh = $('Webhook Backup').first().json || {};
const d = _wh.body || _wh;
const directive = String(d.directive || '');
// El respaldo 3-2-1 es la función principal del empleado: se ejecuta por defecto.
// Solo se omite si el llamante pide explícitamente un dry run.
const dry = d.dry_run === true || d.run_backup === false;
return [{json: {
  dry_run: dry,
  directive,
  task_id: d.task_id || null,
  round_id: d.round_id || null,
  requested_by: d.requested_by || 'director'
}}];

const _wh = $('Webhook Backup').first().json || {};
const d = _wh.body || _wh;
const p = $('Preparar Backup').first().json || {};
const t = $('Tools Backup').first().json || {};
const h = $('Historial Backup').first().json || {};
const last = (h.backups || [])[0] || {};
const findings = [];
if (t.ok === false) findings.push({level:'CRIT', text:'Falló la creación del respaldo: ' + String(t.error || '').slice(0,200)});
if ((t.missing || []).length) findings.push({level:'CRIT', text:'Artefactos faltantes: ' + t.missing.join(', ')});
if (last.ok === 1) findings.push({level:'OK', text:'Último respaldo verificado ' + last.name + ' (' + last.bytes_total + ' bytes)'});
if (!findings.length) findings.push({level:'OK', text:p.dry_run ? 'Modo seco: sin escritura; plan 3-2-1 listo para la ronda nocturna' : 'Respaldoverificado con integridad'});
const severity = findings.some(f => f.level === 'CRIT') ? 'CRIT' : 'OK';
const evidence = JSON.stringify({dry_run:p.dry_run, result:t, history:(h.backups||[]).slice(0,8)}).slice(0,4500);
const prompt = `Eres Agent-Backup, responsable del respaldo 3-2-1 de HomeLab Corp.
Tu jefe es HomeLab-Director. Informa en 3 a 5 líneas en español: destino, artefactos
verificados, integridad, retención de 7 días y último respaldo real. Nunca includes
rutas de credenciales ni propongas borrar datos personales. No inventes resultados.

MODO: ${p.dry_run ? 'SECO (sin cambios)' : 'RESPALDO REAL'}
EVIDENCIA:
${evidence}

HALLAZGOS:
${JSON.stringify(findings)}
`;
return [{json: {
  employee:'Agent-Backup', severity, quality_score:0.9, findings, evidence, prompt,
  directive:d.directive || p.directive || '', task_id:d.task_id || p.task_id || null,
  round_id:d.round_id || p.round_id || null, tool_data:t
}}];

const a = $('Analizar Backup').first().json || {};
const l = $('LLM Backup').first().json || {};
const choices = l.choices || [];
const text = ((choices[0] && choices[0].message && choices[0].message.content) || '').trim();
return [{json: {
  employee: a.employee,
  severity: a.severity,
  quality_score: a.quality_score,
  summary: (text || a.summary || 'Sin hallazgos').slice(0, 2500),
  findings: a.findings || [],
  evidence: a.evidence || '',
  directive: a.directive || '',
  task_id: a.task_id || null,
  round_id: a.round_id || null
}}];

const r = $('Rendir cuentas Backup').first().json || {};
const d = $('Redactar informe Backup').first().json || {};
return [{json: {...d, report_id: r.report_id || null, ledger_ok: !!r.ok}}];
